export default {
  baseURL: '/api/v1',

  async get(path) {
    const res = await fetch(`${this.baseURL}${path}`);
    return res.json();
  },

  async post(path, data) {
    const res = await fetch(`${this.baseURL}${path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    return res.json();
  },
};
